import{_ as t,o,c as l,a8 as i}from"./chunks/framework.DQoZbSQ3.js";const g=JSON.parse('{"title":"Cline 接入熊猫算力教程","description":"","frontmatter":{"title":"Cline 接入熊猫算力教程","date":"2026-05-18T00:00:00.000Z","category":"拓展连接","tags":["Cline","VS Code","AI编程"]},"headers":[],"relativePath":"connect/cline.md","filePath":"connect/cline.md","lastUpdated":1779095428000}'),a={name:"connect/cline.md"};function n(d,e,r,c,s,h){return o(),l("div",null,[...e[0]||(e[0]=[i('<h2 id="什么是-cline" tabindex="-1">什么是 Cline <a class="header-anchor" href="#什么是-cline" aria-label="Permalink to &quot;什么是 Cline&quot;">​</a></h2><p>Cline 是 VS Code 的开源 AI 编程插件，支持代码生成、文件操作、终端命令执行，功能类似 Claude Code，但集成在 VS Code 界面内，对习惯图形界面的开发者更友好。</p><h2 id="安装-cline" tabindex="-1">安装 Cline <a class="header-anchor" href="#安装-cline" aria-label="Permalink to &quot;安装 Cline&quot;">​</a></h2><ol><li>打开 VS Code</li><li>进入扩展商店（Ctrl+Shift+X）</li><li>搜索 <strong>Cline</strong></li><li>点击安装</li></ol><h2 id="配置熊猫算力" tabindex="-1">配置熊猫算力 <a class="header-anchor" href="#配置熊猫算力" aria-label="Permalink to &quot;配置熊猫算力&quot;">​</a></h2><ol><li>安装完成后，点击左侧 Cline 图标</li><li>进入 <strong>Settings</strong></li><li><strong>API Provider</strong> 选择 <code>OpenAI Compatible</code></li><li>填写以下信息： <ul><li><strong>API Key</strong>：你的熊猫算力 Key</li><li><strong>Base URL</strong>：<code>https://c.pandatoken.com/v1</code></li><li><strong>Model</strong>：<code>claude-sonnet-4-6</code>（或其他你需要的模型）</li></ul></li><li>点击保存</li></ol><h2 id="推荐模型配置" tabindex="-1">推荐模型配置 <a class="header-anchor" href="#推荐模型配置" aria-label="Permalink to &quot;推荐模型配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>用途</th><th>推荐模型</th></tr></thead><tbody><tr><td>日常代码编写</td><td><code>claude-sonnet-4-6</code></td></tr><tr><td>复杂架构设计</td><td><code>claude-opus-4-7</code></td></tr><tr><td>快速补全</td><td><code>claude-haiku-4-5-20251001</code></td></tr><tr><td>性价比优先</td><td><code>deepseek-v4-pro</code></td></tr></tbody></table><h2 id="基本使用" tabindex="-1">基本使用 <a class="header-anchor" href="#基本使用" aria-label="Permalink to &quot;基本使用&quot;">​</a></h2><ul><li><strong>新建任务</strong>：在 Cline 面板输入需求，如&quot;帮我写一个用户登录接口&quot;</li><li><strong>文件操作</strong>：Cline 会自动读取和修改项目文件，每次操作需要确认</li><li><strong>终端命令</strong>：可以执行 npm install、git commit 等命令，执行前会提示确认</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Cline 默认会读取项目所有文件，大型项目注意控制上下文范围，避免 Token 消耗过大。建议在 <code>.clineignore</code> 文件中排除 <code>node_modules</code>、<code>.git</code> 等目录。</p></div>',11)])])}const p=t(a,[["render",n]]);export{g as __pageData,p as default};
